import zones from './countryTimezones.json';

export interface CountryZone {
  id: string;
  en: string;
  fr: string;
  de: string;
  es: string;
}

/**
 * Country code → IANA zones. Data is `countryTimezones.json`, generated by
 * `scripts/generate-country-timezones.mjs` from tzdata `zone1970.tab`.
 * The same file is the server's zone list. The first zone is the default.
 */
export const COUNTRY_ZONES: Record<string, readonly CountryZone[]> = zones;
